INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-enigma-del-objeto-oculto', 'El Enigma del Objeto Oculto', 'Dinámica de atención visual y autocontrol donde los participantes ubican un objeto expuesto a la vista y se sientan en silencio.', '<h2>📜 Descripción de El Enigma del Objeto Oculto</h2>
<p><b>El Enigma del Objeto Oculto</b> es una dinámica de atención sostenida, agudeza de observación y autocontrol en grupo. Para iniciar, la unidad sale momentáneamente del salón. El dirigente coloca un objeto pequeño (como una moneda brillante, una argolla o un dedal) en un lugar expuesto a plena vista sobre una repisa, mueble o adorno, pero ubicado de modo que se mimetice de forma natural con el entorno sin estar escondido debajo o detrás de nada.</p>
<p>Los participantes ingresan a la sala y comienzan a caminar en silencio buscando con la mirada sin tocar nada. En el instante exacto en que un scout localiza visualmente el objeto, no lo señala ni grita, sino que se sienta de inmediato en el suelo en silencio total, disimulando su mirada para no delatar la posición a los demás.</p>
<p>Esta dinámica ejercita la capacidad de observación detallada, el respeto al silencio colectivo y la honestidad en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Enigma del Objeto Oculto?</h2>
<p>Para llevar a cabo la dinámica con misterio y observación, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Aislamiento Breve:</b> El grupo espera fuera de la sala mientras el dirigente ubica el objeto a plena vista.</li>
  <li><b>Ingreso y Rastrillaje Visual:</b> Los scouts caminan por la sala observando los rincones con atención.</li>
  <li><b>Reacción en Silencio:</b> Quien vea el objeto se sienta en el suelo en silencio sin mirarlo fijamente.</li>
  <li><b>Verificación y Cierre:</b> Al finalizar el tiempo o cuando la mayoría esté sentada, el primer scout indica dónde está el objeto.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Enigma del Objeto Oculto</h2>
<p>La actividad valora la agudeza visual y la honestidad en el Tally:</p>
<ul>
  <li><b>Primer Observador:</b> Otorgar 5 puntos al participante que descubra primero el objeto sin delatarlo.</li>
  <li><b>Autocontrol y Silencio:</b> Otorgar 3 puntos a la seisena o patrulla que se siente en completo silencio sin hacer trampas.</li>
  <li><b>Honestidad Comprobada:</b> Otorgar 3 puntos extra si la ubicación descrita al final coincide exactamente con la real.</li>
</ul>', '/uploads/el-enigma-del-objeto-oculto.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "10 minutos", "cantidad": "08 participantes", "lugares": ["Interior", "Salón", "Sala"], "materiales": ["Moneda", "Anillo", "Dedal"], "objetivos": ["Estimular la atención a los detalles", "Estimular la observación", "Reforzar el poner atención", "Trabajo en equipo"], "justificacion_areas": "El Enigma del Objeto Oculto potencia la creatividad al desarrollar la concentración visual sostenida y la agudeza de observación espacial. Desarrolla la sociabilidad al afianzar el autocontrol individual, la honestidad y el respeto al silencio del grupo.", "variaciones": "<b>Ronda de Verificación de Tramposos:</b> Realizar una ronda donde no se coloca ningún objeto para verificar si alguien se sienta por imitación.<br><b>Dos Objetos Ocultos:</b> Colocar dos objetos pequeños y exigir que el scout diga el nombre del objeto que vio al sentarse.<br><b>Objeto Oculto en Exterior:</b> Ubicar una pequeña piña pintada en la rama de un árbol a plena vista.", "recomendaciones": "Asegurar que el objeto esté 100% visible a la vista sin estar cubierto por ningún elemento.", "objetivos_educativos": [{"id": "a2ef0709-ac6d-4d90-9fe8-c96eeff5cf14", "area": "Creatividad", "unidad": "Manada", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Buscando con la mirada atenta por todo el salón hasta encontrar la monedita guardando el secreto."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Sentándome en el suelo calladito apenas veo la moneda sin avisarle a los demás con la boca ni con señas."}, {"id": "418f2b77-f15b-405a-95bd-8033c0b6a4c2", "area": "Creatividad", "unidad": "Manada", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Mirando los estantes con paciencia hasta descubrir el objeto que está a la vista de todos."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Respetando el juego limpio y sentándome solo cuando estoy seguro de haber visto la moneda."}, {"id": "11320fb6-98de-4725-825d-db858e3bffa2", "area": "Creatividad", "unidad": "Compañía", "texto": "Perfecciono mis habilidades manuales.", "como_se_cumple": "Ejercitando la agudeza de observación visual y el rastreo de detalles en el entorno."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Guardando compostura y silencio al ubicar el objeto para permitir que mis compañeras sigan buscando."}, {"id": "4e6b0cd4-85bb-404b-9af2-36fd5b2a4f04", "area": "Creatividad", "unidad": "Compañía", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Descifrando patrones de camuflaje visual con rapidez y discreción."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Demostrando autocontrol y honestidad estricta al acatar el reglamento del silencio."}, {"id": "103661fc-3396-4eac-9182-58b7e54d5115", "area": "Creatividad", "unidad": "Tropa", "texto": "Perfecciono mis habilidades manuales.", "como_se_cumple": "Ejercitando la agudeza de observación visual y el rastreo de detalles en el entorno."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Guardando compostura y silencio al ubicar el objeto para permitir que mis compañeros sigan buscando."}, {"id": "9fe305a1-531d-47b6-9aaa-e7d6b2dbd3b1", "area": "Creatividad", "unidad": "Tropa", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Descifrando patrones de camuflaje visual con rapidez y discreción."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Demostrando autocontrol y honestidad estricta al acatar el reglamento del silencio."}, {"id": "fe57c89e-be7b-46a1-b370-64df400355fa", "area": "Creatividad", "unidad": "Avanzada", "texto": "Trato de aprender más sobre cuestiones técnicas relacionadas con el sonido, la imagen, la mecánica, la informática y otros.", "como_se_cumple": "Desarrollando la concentración sostenida y el autocontrol visual en la Avanzada."}, {"id": "7e7417a5-a16e-4ff3-843f-93e711d017d4", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Fomentando la honestidad y el respeto por las normas del juego en equipo."}, {"id": "29eee8b1-a414-4df9-90e1-520a384fb9aa", "area": "Creatividad", "unidad": "Clan", "texto": "Uno los conocimientos teórico y práctico mediante la aplicación constante de mis habilidades técnicas y manuales.", "como_se_cumple": "Aplicando capacidad de observación sutil y paciencia en la resolución del desafío."}, {"id": "c4f78e61-6790-4cf4-b477-993900b5bf02", "area": "Sociabilidad", "unidad": "Clan", "texto": "Contribuyo a preserv